SELECT id, student_no, class_name, used, created_at
FROM student_whitelist
WHERE 1 = 1

    AND used = #{used}


    AND (student_no LIKE CONCAT('%', #{keyword}, '%')
         OR class_name LIKE CONCAT('%', #{keyword}, '%')
         OR name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM student_whitelist WHERE 1 = 1
AND used = #{used}
AND (student_no LIKE CONCAT('%', #{keyword}, '%') OR class_name LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%'))
